draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // heart
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 50 + 20 * Math.sin(t));
  ctx.bezierCurveTo(W/2 - 30, H/2 - 70 + 20 * Math.sin(t), W/2 - 60, H/2 + 20 * Math.sin(t), W/2, H/2 + 60 + 20 * Math.sin(t));
  ctx.bezierCurveTo(W/2 + 60, H/2 + 20 * Math.sin(t), W/2 + 30, H/2 - 70 + 20 * Math.sin(t), W/2, H/2 - 50 + 20 * Math.sin(t));
  ctx.stroke();

  // brain
  ctx.beginPath();
  ctx.arc(W/2 + 80, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // connection
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 40 + 10 * Math.sin(t));
  ctx.lineTo(W/2 + 60, H/2 - 10 + 10 * Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
